  assign mem_to_reg[0] = \mem_to_reg[0] ;
  assign alu_src = \alu_op[1] ;
  assign alu_op[1] = \alu_op[1] ;

  NAND2X0_HVT U3 ( .IN1(opcode[0]), .IN2(n1), .QN(sign_or_zero) );
  NAND2X0_HVT U4 ( .IN1(n2), .IN2(n3), .QN(reg_write) );
  INVX0_HVT U5 ( .INP(n4), .ZN(n3) );
